# Gives the shortcut groups migration 0152_menus created their icon, matched
# by the nb titles it used. Only fills in blank icons, so anything already
# picked in the admin is left alone.
ICON_BY_NB_TITLE = {
    "Info": "info",
    "Infoartikkler": "info",
    "Nyheter": "news",
    "Foreninger": "unions",
    "Studentforeninger": "unions",
    "Stillingsannonser": "jobs",
    "Arrangementer": "events",
    "Verktøy": "tools",
}


def set_default_icons(apps, schema_editor):
    MenuGroup = apps.get_model("ifi_home_app", "MenuGroup")
    for group in MenuGroup.objects.filter(locale__language_code="nb", icon=""):
        icon = ICON_BY_NB_TITLE.get(group.title)
        if icon:
            MenuGroup.objects.filter(
                translation_key=group.translation_key, icon=""
            ).update(icon=icon)


